/// <summary>
/// N.Freidenberger 15-07-2025
/// </summary>
internal final class AVAItemCycleCountStart
{
    ItemId                          itemId;
    InventLocationId                inventLocationId;
    WHSParameters                   parameters;
    LineNum                         workLineNum;
    RefRecId                        itemCycleOverviewLineRefRecId;
    WMSLocationId                   recountWMSLocationId; 

}

