/// <summary>
/// N.Freidenberger 30-07-2025
/// </summary>
/// <param name = "_recountWMSLocationId">_recountWMSLocationId</param>
/// <returns>parmRecountStart</returns>
public WMSLocationId parmRecountWMSLocationId(WMSLocationId     _recountWMSLocationId = recountWMSLocationId)
{
    recountWMSLocationId = _recountWMSLocationId;
    return recountWMSLocationId;
}

/// <summary>
/// N.Freidenberger 08.07.2025
/// </summary>
/// <param name = "_itemCycleCountOverviewLine">_itemCycleCountOverviewLine</param>
/// <returns>AVAItemCycleCountStart</returns>
public static AVAItemCycleCountStart  newFromItemCycleCountOverviewLine(AVAItemCycleCountOverviewLine       _itemCycleCountOverviewLine)
{

    AVAItemCycleCountStart    AVAItemCycleCountStart = new AVAItemCycleCountStart();
    AVAItemCycleCountStart.parmItemId(_itemCycleCountOverviewLine.ItemId); 
    AVAItemCycleCountStart.parminventLocationId(_itemCycleCountOverviewLine.InventLocationId);
    AVAItemCycleCountStart.parmItemCycleOverviewLineRefRecId(_itemCycleCountOverviewLine.RecId);

    return AVAItemCycleCountStart;
}

