/// <summary>
/// N.Freidenberger 08.07.2025
/// </summary>
/// <param name = "_inventLocationId">_inventLocationId</param>
/// <returns>inventLocationId</returns>
public inventLocationId   parminventLocationId (inventLocationId _inventLocationId = inventLocationId)
{
    inventLocationId         = _inventLocationId;
    return inventLocationId;
}

/// <summary>
/// N.Freidenberger 08.07.2025
/// </summary>
/// <returns>int</returns>
public boolean start()
{
    boolean createdCycleItem;

    InventLocation      inventLocation = InventLocation::find(inventLocationId);
    parameters = WHSParameters::find();

    Query       inventOnHandQuery = new Query(queryStr(InventOnHand));
    QueryRun    queryRun;
    InventSum   inventSum;
    InventDim   inventDim;

    QueryBuildDataSource        wmsLocationDS;
    QueryBuildDataSource        whsLocationProfileDS;

    WMSLocation                 wmsLocation;
    WHSLocationProfile          whsLocationProfile;

    WMSLocationId               prvWMSLocationId;

    WHSWorkId                   createdWorkId;
    InventJournalId             createdInventJournalId;

    inventOnHandQuery.dataSourceTable(tableNum(InventDim)).addGroupByField(fieldNum(InventDim,InventLocationId));
    inventOnHandQuery.dataSourceTable(tableNum(InventSum)).addGroupByField(fieldNum(InventSum,ItemId));
    inventOnHandQuery.dataSourceTable(tableNum(InventDim)).addGroupByField(fieldNum(InventDim,wMSLocationId));
    inventOnHandQuery.dataSourceTable(tablenum(InventDim)).addGroupByField(fieldNum(InventDim,InventColorId));
    inventOnHandQuery.dataSourceTable(tableNum(InventDim)).addGroupByField(fieldnum(InventDim,InventSiteId));
    inventOnHandQuery.dataSourceTable(tableNum(InventSum)).addSelectionField(fieldNum(InventSum,PhysicalInvent),SelectionField::Sum);
    //inventOnHandQuery.dataSourceTable(tableNum(InventSum)).addRange(fieldNum(InventSum,PhysicalInvent)).value('> 0');
    inventOnHandQuery.dataSourceTable(tableNum(InventDim)).addRange(fieldNum(InventDim,wMSLocationId)).value(SysQuery::valueNotEmptyString());
    inventOnHandQuery.dataSourceTable(tableNum(InventDim)).addRange(fieldNum(InventDim,InventLocationId)).value(inventLocationId);
    inventOnHandQuery.dataSourceTable(tableNum(InventSum)).addRange(fieldNum(InventSum,ItemId)).value(itemId);
    inventOnHandQuery.dataSourceTable(tableNum(InventDim)).addSortField(fieldNum(InventDim,wMSLocationId),SortOrder::Ascending);


    wmsLocationDS = inventOnHandQuery.dataSourceTable(tableNum(InventDim)).addDataSource(tableNum(WMSLocation));
    wmsLocationDS.joinMode(JoinMode::InnerJoin);
    wmsLocationDS.addLink(fieldNum(InventDim,wmsLocationId),fieldNum(wMSLocation,wmsLocationId));

    if (recountWMSLocationId)
    {
        wmsLocationDS.addRange(fieldNum(WMSLocation,wMSLocationId)).value(recountWMSLocationId);
    }

    whsLocationProfileDS = wmsLocationDS.addDataSource(tableNum(WHSLocationProfile));
    whsLocationProfileDS.joinMode(JoinMode::OuterJoin);
    whsLocationProfileDS.addLink(fieldNum(WMSLocation,LocProfileId),fieldNum(WHSLocationProfile,LocProfileId));
    //whsLocationProfileDS.addSelectionField(fieldNum(whsLocationProfile,CycleCountable),SelectionField::Min);
    //whsLocationProfileDS.addRange(fieldNum(WHSLocationProfile,CycleCountable)).value(SysQuery::value(NoYes::Yes));


    queryRun = new QueryRun(inventOnhandQuery);
    while (queryRun.next())
    {
        inventSum           = queryRun.get(tableNum(InventSum));
        inventDim           = queryRun.get(tableNum(InventDim));
        wmsLocation         = queryRun.get(tableNum(WMSLocation));
        whsLocationProfile  = queryRun.get(tableNum(whsLocationProfile));

        whsLocationProfile  = queryRun.get(tableNum(whsLocationProfile));
        if ((whsLocationProfile.RecId &&  whsLocationProfile.CycleCountable == NoYes::Yes) || !whsLocationProfile.RecId )
        {
            if (inventLocation.WHSEnabled && inventSum.PhysicalInvent > 0)
            {
                createdWorkId = this.createCycleCountWork(prvWMSLocationId == inventDim.wMSLocationId ? createdWorkId : '',inventDim);
            }
            else
            {
                createdInventJournalId = this.createCycleCountInvJournal(createdInventJournalId, inventDim);
            }
        }
        prvWMSLocationId = inventDim.wMSLocationId;

    }

    AVAItemCycleCountOverviewLine           locItemCycleCountOverviewLine = AVAItemCycleCountOverviewLine::find(itemId,InventLocationId,true);
    locItemCycleCountOverviewLine.InventJournalId = createdInventJournalId;

    if (createdWorkId || createdInventJournalId)
    {
        locItemCycleCountOverviewLine.ItemCycleCountStarted = NoYes::Yes;


        ttsbegin;
        locItemCycleCountOverviewLine.update();
        ttscommit;
        this.blockInventItemLocation(createdInventJournalId);
    }
    return createdCycleItem;
}

/// <summary>
/// N.Freidenberger 09.07.2025
/// </summary>
/// <param name = "_inventJournalId">_inventJournalId</param>
protected void blockInventItemLocation(InventJournalId   _inventJournalId)
{
    InventItemLocation      inventItemLocation;
    InventDim               locInventDim;
    InventItemLocationCountingStatus        inventItemLocationCountingStatus;

    select firstonly  inventItemLocation
    where inventItemLocation.ItemId ==   itemId
        join locInventDim
            where locInventDim.inventDimId == inventItemLocation.inventDimId
    && locInventDim.InventLocationId == inventLocationId
        outer join inventItemLocationCountingStatus
            where inventItemLocationCountingStatus.ItemId == inventItemLocation.ItemId
                && InventItemLocationCountingStatus.InventDimId == inventItemLocation.inventDimId;

    if (inventItemLocation)
    {
        if (!inventItemLocationCountingStatus)
        {
            inventItemLocationCountingStatus.ItemId         = itemId;
            inventItemLocationCountingStatus.InventDimId    = inventItemLocation.inventDimId;
        }

        inventItemLocationCountingStatus.CountingStarted    = NoYes::Yes;
        inventItemLocationCountingStatus.CountingJournalId  = _inventJournalId;
        inventItemLocationCountingStatus.selectForUpdate(true);
        ttsbegin;
        inventItemLocationCountingStatus.write();
        ttscommit;
    }

}

/// <summary>
/// N.Freidenberger 15-07-2025
/// </summary>
 /// <param name = "_whsWorkId">_whsWorkId</param>
 /// <param name = "_inventDim">_inventDim</param>
 /// <returns>WHSWorkId</returns>
protected WHSWorkId createCycleCountWork(WHSWorkId      _whsWorkId, InventDim       _inventDim)
{
     WHSWorkId           createdWork = _whsWorkId;
     WHSWorkTable        newWorkTable;


     WHSWorkCreateId  workCreateId; 

     if (createdWork == '')
     {
         workCreateId = WHSWorkTable::getNextWorkCreateId();
         newWorkTable.clear();
         newWorkTable.setWorkId();
         newWorkTable.WorkBuildId             = workCreateId;
         newWorkTable.WorkTransType           = WHSWorkTransType::CycleCount;
         newWorkTable.InventSiteId            = _inventDim.InventSiteId;
         newWorkTable.InventLocationId        = _inventDim.InventLocationId;
         newWorkTable.WorkPriority            = parameters.CycleCountWorkPriority ? parameters.CycleCountWorkPriority : parameters.WorkPriority;
         newWorkTable.TransTxt                = itemId  + ' / LP:' + _inventDim.wmsLocationId;
         newWorkTable.WorkCreatedBy           = curUserId();
         newWorkTable.IsPartialCycleCountWork = NoYes::Yes;
         newWorkTable.avaInitFromWorkRemplateCycleCount(parameters.AVAWorkTemplateCodeCycleCount);

         if (recountWMSLocationId)                        
         {
             newWorkTable.WorkPoolId     = parameters.AVAWorkPoolIdRecount;
             newWorkTable.WorkPriority   = parameters.AVAWorkPriorityRecount; 
         }
         //newWorkTable.WorkPoolId         = workPoolId;
         newWorkTable.insert();

         createdWork = newWorkTable.WorkId;

         workLineNum = 0;

         this.writeItemCycleCountOverviewObject(AVAItemCycleCountObject::WorkTable,createdWork);
     }

     InventDim newInventDim;
     newInventDim.InventLocationId = _inventDim.inventLocationId;
     newInventDim.InventSiteId     = _inventDim.InventSiteId;
     newInventDim.wMSLocationId    = _inventDim.wMSLocationId;
     newInventDim.InventColorId    = _inventDim.InventColorId;
     newInventDim = InventDim::findOrCreate(newInventDim);

     WHSWorkLine newWorkLine;

     workLineNum ++;
     newWorkLine.WorkId          = newWorkTable.WorkId;
     newWorkLine.LineNum         = workLineNum;
     newWorkLine.WorkType        = WHSWorkType::Count;
     newWorkLine.WMSLocationId   = newInventDim.wMSLocationId;
     newWorkLine.InventDimId     = newInventDim.inventDimId;
     newWorkLine.Mandatory       = NoYes::Yes;
     newWorkLine.WorkClassId     = parameters.DefaultCycleCountWorkClassId;
     newWorkLine.ItemId          = itemId;

     newWorkLine.insert();


     return createdWork;
 }

/// <summary>
/// N.Freidenberger 09-07-2025
/// </summary>
/// <param name = "_createdInventJournalId">_createdInventJournalId</param>
/// <param name = "_inventDim">_inventDim</param>
/// <returns>InventJournalId</returns>
protected InventJournalId  createCycleCountInvJournal(InventJournalId        _createdInventJournalId, InventDim      _inventDim)
{
    InventJournalTable              inventJournalTable;
    InventJournalTrans              inventJournalTrans;
    InventJournalNameId             inventJournalNameId;
    InventJournalId                 createdJournalId;      


    createdJournalId = _createdInventJournalId;

    if (_createdInventJournalId == '')
    {
        inventJournalTable.clear();
        inventJournalNameId = InventJournalName::standardJournalName(InventJournalType::Count);

        inventJournalTable.initFromInventJournalName(InventJournalName::find(inventJournalNameId));
        inventJournalTable.InventSiteId = _inventDim.InventSiteId;
        inventJournalTable.InventLocationId = _inventDim.InventLocationId;
        inventJournalTable.InventDimFixed   = this.initInventDimParm().inventDimFixed();
        inventJournalTable.Description += ' ' + itemId;
        inventJournalTable.insert();
        createdJournalId = inventJournalTable.JournalId;

        this.writeItemCycleCountOverviewObject(AVAItemCycleCountObject::InventJournal,inventJournalTable.JournalId);
    }

    InventDim       newInventDim;
    newInventDim.InventLocationId = _inventDim.inventLocationId;
    newInventDim.InventSiteId     = _inventDim.InventSiteId;
    newInventDim.wMSLocationId    = _inventDim.wMSLocationId;
    newInventDim.InventColorId    = _inventDim.InventColorId;
    newInventDim = InventDim::findOrCreate(newInventDim);


    inventJournalTrans.clear();
    inventJournalTrans.initValue();
    inventJournalTrans.initFromInventJournalTable(inventJournalTable);
    inventJournalTrans.ItemId = itemId;
    inventJournalTrans.initFromInventTable(InventTable::find(itemId));
    inventJournalTrans.InventDimId = newInventDim.inventDimId;


    inventJournalTrans.insert();

    return createdJournalId;
}

/// <summary>
/// N.Freidenberger 09-07-2025
/// </summary>
/// <returns>InventDimParm</returns>
protected InventDimParm   initInventDimParm()
{
    InventDimParm       inventDimParm;
    inventDimParm.clear();
    inventDimParm.InventSiteIdFlag     = NoYes::Yes;
    inventDimParm.InventLocationIdFlag = NoYes::Yes;
    inventDimParm.WMSLocationIdFlag    = NoYes::Yes;
    inventDimParm.InventColorIdFlag    = NoYes::Yes;

    return inventDimParm;
}

/// <summary>
/// N.Freidenberger 09-07-2025
/// </summary>
/// <param name = "_cycleObjectType">_cycleObjectType</param>
/// <param name = "_cycleObjectId">_cycleObjectId</param>
protected void writeItemCycleCountOverviewObject(AVAItemCycleCountObject _cycleObjectType, Num   _cycleObjectId)
{
    AVAItemCycleCountOverviewObject     itemCycleCountOverviewObject;

    itemCycleCountOverviewObject.clear();
    itemCycleCountOverviewObject.ItemCycleCountOverviewLine = itemCycleOverviewLineRefRecId;
    itemCycleCountOverviewObject.ItemCycleCountObject       = _cycleObjectType;
    itemCycleCountOverviewObject.ObjectId                   = _cycleObjectId;
    itemCycleCountOverviewObject.ItemId                     = itemId;
    itemCycleCountOverviewObject.InventLocationId           = inventLocationId;
    itemCycleCountOverviewObject.insert();
}
